"""Intent tests for mdata.validate_rows (M1-T14, DATA-02, TC-01)."""

from __future__ import annotations

import dataclasses
from collections.abc import Callable

import pytest

from mdata import RawRow, validate_rows


def _rows(raw: list[list[object]]) -> list[RawRow]:
    return [RawRow(date=d, ticker=t, close=c) for d, t, c in raw]  # type: ignore[arg-type]


@pytest.mark.intent
def test_tc01_drops_unusable_rows_keeps_later_duplicate_sorted(
    golden: Callable[[str, str], tuple[dict, dict]],
) -> None:
    given, expected = golden("mdata", "TC-01")
    result = validate_rows(_rows(given["rows"]), given["tickers"])
    assert result == _rows(expected["rows"])


@pytest.mark.intent
def test_tc01_result_does_not_depend_on_tickers_default(
    golden: Callable[[str, str], tuple[dict, dict]],
) -> None:
    given, expected = golden("mdata", "TC-01")
    result = validate_rows(_rows(given["rows"]))
    assert result == _rows(expected["rows"])


@pytest.mark.intent
def test_sample_rows_are_positive_unique_and_sorted(
    contract_sample: Callable[[str], dict],
) -> None:
    rows = [RawRow(**row) for row in contract_sample("mdata.RawRow")["rows"]]
    result = validate_rows(list(reversed(rows)))
    blank = [r for r in rows if r.close is None]
    assert len(result) == len(rows) - len(blank)
    assert all(r.close is not None and r.close > 0 for r in result)
    keys = [(r.date, r.ticker) for r in result]
    assert keys == sorted(set(keys))
    assert set(result) == {r for r in rows if r.close is not None}


@pytest.mark.intent
def test_unknown_requested_ticker_is_a_key_error_naming_it(
    contract_sample: Callable[[str], dict],
) -> None:
    rows = [RawRow(**row) for row in contract_sample("mdata.RawRow")["rows"]]
    with pytest.raises(KeyError, match="ZZZQ"):
        validate_rows(rows, ["ACME", "ZZZQ"])


@pytest.mark.intent
def test_ticker_with_only_unusable_rows_is_a_key_error_naming_it(
    contract_sample: Callable[[str], dict],
) -> None:
    rows = [RawRow(**row) for row in contract_sample("mdata.RawRow")["rows"]]
    unusable = [-1.0, 0.0, None]
    rows = [
        dataclasses.replace(r, close=unusable[i % 3]) if r.ticker == "BOLT" else r
        for i, r in enumerate(rows)
    ]
    with pytest.raises(KeyError, match="BOLT"):
        validate_rows(rows, ["ACME", "BOLT"])

